import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

interface NodeConfig {
  imageUrl?: string;
  textContent?: Array<{
    text: string;
    fontSize?: number;
    color?: string;
    fontFamily?: string;
  }>;
  scenePosition?: {
    x?: number;
    y?: number;
    z?: number;
    rotationXYZ?: [number, number, number];
    scaleXYZ?: [number, number, number];
  };
  cinematicPrimitives?: Array<{
    name: string;
    params?: Record<string, any>;
  }>;
}

interface NodeContext {
  textureLoader: {
    load(url: string): THREE.Texture;
  };
  fontAtlas: {
    createText(text: string, options: Record<string, any>): THREE.Object3D;
  };
  primitives?: {
    [key: string]: (target: THREE.Object3D, params?: Record<string, any>) => void;
  };
}

export default function createNode(config: NodeConfig, ctx: NodeContext): THREE.Object3D {
  const group = new THREE.Group();

  const resources = {
    geometries: [] as THREE.BufferGeometry[],
    materials: [] as THREE.Material[],
    textures: [] as THREE.Texture[],
  };

  // Apply scene position from config
  if (config.scenePosition) {
    group.position.set(
      config.scenePosition.x ?? 0,
      config.scenePosition.y ?? 0,
      config.scenePosition.z ?? 0
    );
    if (config.scenePosition.rotationXYZ) {
      group.rotation.order = 'XYZ';
      group.rotation.set(
        config.scenePosition.rotationXYZ[0] ?? 0,
        config.scenePosition.rotationXYZ[1] ?? 0,
        config.scenePosition.rotationXYZ[2] ?? 0
      );
    }
    if (config.scenePosition.scaleXYZ) {
      group.scale.set(
        config.scenePosition.scaleXYZ[0] ?? 1,
        config.scenePosition.scaleXYZ[1] ?? 1,
        config.scenePosition.scaleXYZ[2] ?? 1
      );
    }
  }

  // Create plane geometry
  const planeGeometry = new THREE.PlaneGeometry(1, 1);
  resources.geometries.push(planeGeometry);

  // Load texture from imageUrl
  let texture: THREE.Texture | null = null;
  if (config.imageUrl) {
    texture = ctx.textureLoader.load(config.imageUrl);
    texture.colorSpace = THREE.SRGBColorSpace;
    resources.textures.push(texture);
  }

  // Create material
  const material = new THREE.MeshBasicMaterial({
    map: texture ?? undefined,
    side: THREE.DoubleSide,
    transparent: true,
  });
  resources.materials.push(material);

  // Create mesh
  const mesh = new THREE.Mesh(planeGeometry, material);
  group.add(mesh);

  // Render text content via fontAtlas
  if (config.textContent && config.textContent.length > 0) {
    const textSpec = config.textContent[0];
    if (textSpec.text) {
      const textObject = ctx.fontAtlas.createText(textSpec.text, {
        fontSize: textSpec.fontSize ?? 0.13,
        fontFamily: textSpec.fontFamily ?? 'JetBrains Mono',
        color: textSpec.color ?? new THREE.Color(0x16161d),
        align: 'center',
      });

      textObject.position.z = 0.01;
      textObject.position.y = -0.2;
      group.add(textObject);
    }
  }

  // Setup cleanup
  group.userData.cleanup = () => {
    resources.geometries.forEach(g => g.dispose());
    resources.materials.forEach(m => m.dispose());
    resources.textures.forEach(t => t.dispose());
    gsap.killTweensOf(group);
  };

  // Setup event handlers
  group.userData.handlers = {
    onClick: undefined,
    onPointerOver: undefined,
    onPointerOut: undefined,
  };

  return group;
}
